--
-- TOC entry 241 (class 1259 OID 16900)
-- Name: v_scholarship_lines; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_scholarship_lines AS
 SELECT si.sale_item_id,
    s.sale_id,
    s.sale_date,
    s.sales_channel,
    s.payment_method,
    p.product_id,
    p.product_name,
    p.scholarship_rate,
    si.quantity,
    si.allocated_revenue,
    si.scholarship_amount
   FROM ((public.sale_items si
     JOIN public.sales s ON ((si.sale_id = s.sale_id)))
     JOIN public.products p ON ((si.product_id = p.product_id)))
  WHERE (p.scholarship_rate > (0)::numeric);


