--
-- TOC entry 5060 (class 2618 OID 16898)
-- Name: v_sale_financials _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.v_sale_financials AS
 SELECT s.sale_id,
    s.sale_date,
    s.sales_channel,
    s.payment_method,
    s.state,
    s.county,
    s.total_amount AS product_revenue,
    s.tax_collected,
    s.shipping_revenue,
    s.shopify_fee,
    s.shipping_expense,
    COALESCE(sum(si.quantity), (0)::bigint) AS jars_sold,
    COALESCE(sum(((si.quantity)::numeric * p.unit_cost)), (0)::numeric) AS product_cost,
    COALESCE(sum(si.scholarship_amount), (0)::numeric) AS scholarship,
    (((((s.total_amount + s.shipping_revenue) - s.shopify_fee) - s.shipping_expense) - COALESCE(sum(((si.quantity)::numeric * p.unit_cost)), (0)::numeric)) - COALESCE(sum(si.scholarship_amount), (0)::numeric)) AS estimated_profit
   FROM ((public.sales s
     LEFT JOIN public.sale_items si ON ((s.sale_id = si.sale_id)))
     LEFT JOIN public.products p ON ((si.product_id = p.product_id)))
  GROUP BY s.sale_id;


